# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VAHYİN GELİŞİ SONRASI İLK MÜSLÜMANLAR (SÂBİKÛN-İ EVVELÛN)</text>\n  <rect x="20" y="55" width="152" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="96" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">1. Hz. Hatice (r.a.)</text>\n  <text x="96" y="106" text-anchor="middle" font-size="11" fill="#831843">Peygamberimizin eşi;</text>\n  <text x="96" y="124" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">yeryüzünde iman eden</text>\n  <text x="96" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">İLK İNSAN ve İLK KADIN.</text>\n  <text x="96" y="172" text-anchor="middle" font-size="10" fill="#475569">İlk vahiyden sonra</text>\n  <text x="96" y="188" text-anchor="middle" font-size="10" fill="#475569">en büyük moral desteği.</text>\n  <rect x="186" y="55" width="152" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="262" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">2. Hz. Ali (r.a.)</text>\n  <text x="262" y="106" text-anchor="middle" font-size="11" fill="#1e3a8a">Amcası Ebû Talib\'in</text>\n  <text x="262" y="124" text-anchor="middle" font-size="11" fill="#1e3a8a">oğlu; iman eden</text>\n  <text x="262" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">İLK ÇOCUK / GENÇ.</text>\n  <text x="262" y="172" text-anchor="middle" font-size="10" fill="#475569">Peygamberimizin hanesinde</text>\n  <text x="262" y="188" text-anchor="middle" font-size="10" fill="#475569">büyüyüp terbiye aldı.</text>\n  <rect x="352" y="55" width="152" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="428" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. Hz. Zeyd (r.a.)</text>\n  <text x="428" y="106" text-anchor="middle" font-size="11" fill="#14532d">Zeyd bin Hârise;</text>\n  <text x="428" y="124" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">azatlı kölelerden</text>\n  <text x="428" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">İLK MÜSLÜMAN.</text>\n  <text x="428" y="172" text-anchor="middle" font-size="10" fill="#475569">Ailesi yerine Hz. Peygamber\'in</text>\n  <text x="428" y="188" text-anchor="middle" font-size="10" fill="#475569">yanında kalmayı seçti.</text>\n  <rect x="518" y="55" width="162" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="599" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">4. Hz. Ebû Bekir (r.a.)</text>\n  <text x="599" y="106" text-anchor="middle" font-size="11" fill="#713f12">En yakın dostu; hür</text>\n  <text x="599" y="124" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">yetişkin erkeklerden</text>\n  <text x="599" y="142" text-anchor="middle" font-size="11" font-weight="bold" fill="#713f12">İLK MÜSLÜMAN (Sıddîk).</text>\n  <text x="599" y="172" text-anchor="middle" font-size="10" fill="#475569">Pek çok genç sahabinin</text>\n  <text x="599" y="188" text-anchor="middle" font-size="10" fill="#475569">iman etmesine vesile oldu.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FETRET-İ VAHİY, MÜDDESSİR SURESİ VE GİZLİ DAVET DÖNEMİ</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Teblîğ Emrinin Gelişi</text>\n  <text x="180" y="108" text-anchor="middle" font-size="11" fill="#164e63">• İlk vahiy (Alak 1-5) sonrası bir süre</text>\n  <text x="180" y="126" text-anchor="middle" font-size="11" fill="#164e63">vahiy kesintisi yaşandı (Fetret-i Vahiy).</text>\n  <text x="180" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">• Müddessir Suresi 1-5. Ayetler:</text>\n  <text x="180" y="172" text-anchor="middle" font-size="11" fill="#164e63">«Ey örtünüp bürünen! Kalk ve uyar!</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" fill="#164e63">Rabbini yücelt, elbiseni temiz tut!»</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">Böylece Risalet (Tebliğ) görevi başladı.</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#f3e8ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Gizli Davet ve Dârülerkam (3 Yıl)</text>\n  <text x="520" y="108" text-anchor="middle" font-size="11" fill="#581c87">• İlk 3 yıl İslam\'a davet gizli yürütüldü.</text>\n  <text x="520" y="132" text-anchor="middle" font-size="11" fill="#581c87">• Genç sahabi Erkam bin Ebü\'l-Erkam\'ın</text>\n  <text x="520" y="150" text-anchor="middle" font-size="11" fill="#581c87">Safa Tepesi eteğindeki evi eğitim ve</text>\n  <text x="520" y="168" text-anchor="middle" font-size="11" font-weight="bold" fill="#6d28d9">tebliğ merkezi oldu (Dârülerkam).</text>\n  <text x="520" y="196" text-anchor="middle" font-size="11" fill="#475569">• Hz. Osman, Zübeyr bin Avvam, Talha bin</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" fill="#475569">Ubeydullah, Sa\'d bin Ebî Vakkas iman etti.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN GENÇLİK YILLARI VE GÜVENİLİR KİŞİLİĞİ</text>\n  <line x1="50" y1="130" x2="650" y2="130" stroke="#64748b" stroke-width="3"/>\n  <circle cx="110" cy="130" r="9" fill="#3b82f6"/>\n  <circle cx="270" cy="130" r="9" fill="#22c55e"/>\n  <circle cx="430" cy="130" r="9" fill="#eab308"/>\n  <circle cx="590" cy="130" r="9" fill="#ef4444"/>\n  <rect x="35" y="55" width="150" height="58" rx="6" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="110" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Hilfü\'l-Fudûl (590)</text>\n  <text x="110" y="96" text-anchor="middle" font-size="10" fill="#334155">Erdemliler Topluluğu</text>\n  <rect x="195" y="150" width="150" height="58" rx="6" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="270" y="171" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Hz. Hatice ile Evlilik</text>\n  <text x="270" y="191" text-anchor="middle" font-size="10" fill="#334155">Dürüst ticaret (25 yaş)</text>\n  <rect x="355" y="55" width="150" height="58" rx="6" fill="#fefce8" stroke="#eab308"/>\n  <text x="430" y="76" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Kâbe Hakemliği (605)</text>\n  <text x="430" y="96" text-anchor="middle" font-size="10" fill="#334155">Hacerü\'l-Esved (35 yaş)</text>\n  <rect x="515" y="150" width="150" height="58" rx="6" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="590" y="171" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">Hira &amp; İlk Vahiy (610)</text>\n  <text x="590" y="191" text-anchor="middle" font-size="10" fill="#334155">Tefekkür ve Risalet (40 yaş)</text>\n  <text x="350" y="238" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e293b">Ortak Payda: «Muhammedü\'l-Emîn» (Güvenilir Muhammed) — İlk Müslümanların Tereddütsüz İmanı</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
